mapper.select:
SELECT reply_no ,album_no ,content ,parent_reply_no ,user_name ,reply_date ,reply_state FROM album_comment WHERE parent_reply_no = #{parentReplyNo}
AND album_no = #{albumNo}
ORDER BY reply_no

mapper.insert:

 		SELECT NVL(MAX(reply_no),0) + 1
 		FROM album_comment

 	INSERT INTO album_comment
 			(
 				reply_no
	  			,album_no
	  			,content
	  			,parent_reply_no
	  			,user_name
	  			,reply_date
	  			,reply_state
 			)
 		VALUES
 			(
 				#{replyNo}
 				, #{albumNo}
 				, #{content}
